import java.util.*;
import java.io.*;

public class MinCostFlow {
    static class Edge {
        int to, cap, cost, rev;
        public Edge(int to, int cap, int cost, int rev) {
            this.to = to;
            this.cap = cap;
            this.cost = cost;
            this.rev = rev;
        }
    }

    static final int maxn = 6000;
    static final long inf = Long.MAX_VALUE;
    static int n, s, t;
    static List<Edge>[] G = new ArrayList[maxn];
    static long[] dist = new long[maxn];
    static int[] prevv = new int[maxn], preve = new int[maxn];
    static boolean[] inq = new boolean[maxn];

    static void reset(int _n, int _s, int _t) {
        for (int i = 0; i <= _n; i++) {
            G[i] = new ArrayList<>();
        }
        n = _n;
        s = _s;
        t = _t;
    }

    static void connectEdge(int from, int to, int cap, int cost) {
        G[from].add(new Edge(to, cap, cost, G[to].size()));
        G[to].add(new Edge(from, 0, -cost, G[from].size() - 1));
    }

    static long findMinCostFlow(int flowReq) {
        long total = 0;
        while (flowReq > 0) {
            Arrays.fill(dist, 0, n, inf);
            dist[s] = 0;
            Queue<Integer> q = new LinkedList<>();
            q.offer(s);
            Arrays.fill(inq, false, 0, n, false);
            inq[s] = true;
            while (!q.isEmpty()) {
                int u = q.poll();
                inq[u] = false;
                for (int i = 0; i < G[u].size(); i++) {
                    Edge e = G[u].get(i);
                    if (e.cap > 0 && dist[u] + e.cost < dist[e.to]) {
                        dist[e.to] = dist[u] + e.cost;
                        prevv[e.to] = u;
                        preve[e.to] = i;
                        if (!inq[e.to]) {
                            inq[e.to] = true;
                            q.offer(e.to);
                        }
                    }
                }
            }
            if (dist[t] == inf) return -1;
            int flowD = flowReq;
            for (int v = t; v != s; v = prevv[v]) {
                flowD = Math.min(flowD, G[prevv[v]].get(preve[v]).cap);
            }
            flowReq -= flowD;
            total += (long) flowD * dist[t];
            for (int v = t; v != s; v = prevv[v]) {
                Edge e = G[prevv[v]].get(preve[v]);
                e.cap -= flowD;
                G[v].get(e.rev).cap += flowD;
            }
        }
        return total;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int N = Integer.parseInt(st.nextToken());
        int M = Integer.parseInt(st.nextToken());
        int K = Integer.parseInt(st.nextToken());
        int C = Integer.parseInt(st.nextToken());
        int D = Integer.parseInt(st.nextToken());

        int[] A = new int[58];
        List<Integer>[] H = new ArrayList[57];
        for (int i = 0; i < H.length; i++) {
            H[i] = new ArrayList<>();
        }

        for (int i = 1; i <= K; i++) {
            int X = Integer.parseInt(br.readLine());
            A[X]++;
        }

        for (int i = 0; i < M; i++) {
            st = new StringTokenizer(br.readLine());
            int X = Integer.parseInt(st.nextToken());
            int Y = Integer.parseInt(st.nextToken());
            H[X].add(Y);
            H[Y].add(X);
        }

        reset(5103, 0, 5101);
        for (int i = 2; i <= N; i++) {
            connectEdge(0, i, A[i], 0);
        }

        for (int i = 0; i <= 100; i++) {
            for (int l = 1; l <= N; l++) {
                connectEdge(50 * i + l, 50 * (i + 1) + l, K, 0);
                for (int j : H[l]) {
                    for (int k = 1; k <= K; k++) {
                        connectEdge(50 * i + l, 50 * (i + 1) + j, 1, D * (2 * k - 1));
                    }
                }
            }
        }

        for (int i = 1; i <= 101; i++) {
            connectEdge(50 * i + 1, 5101, K, C * i);
        }

        System.out.println(findMinCostFlow(K));
    }
}
